111	PhysicsBody::~PhysicsBody()
112	{
113	    for (auto& joint : _joints)
114	    {
115	        PhysicsBody* other = joint->getBodyA() == this ? joint->getBodyB() : joint->getBodyA();
116	        other->removeJoint(joint);
117	        delete joint;
118	    }
119	    
120	    if (_cpBody)
121	    {
122	        cpBodyFree(_cpBody);
123	    }
