452	void PhysicsBody::addMass(float mass)
453	{
454	    if (mass == -PHYSICS_INFINITY) return;
455	    if (_massDefault)
456	    {
457	        _mass = 0;
458	        _massDefault = false;
459	    }
460	    _mass += mass;
461	    if (_mass <= 0)
462	    {
463	        _mass = MASS_DEFAULT;
464	        _massDefault = true;
465	    }
466	    _density = (_area > 0 && _mass != PHYSICS_INFINITY) ? (_mass / _area) : 0;
467	}
