660	void PhysicsBody::update(float delta)
661	{
662	    // damping compute
663	    if (_isDamping && _dynamic && !isResting())
664	    {
665	        _cpBody->v.x *= cpfclamp(1.0f - delta * _linearDamping, 0.0f, 1.0f);
666	        _cpBody->v.y *= cpfclamp(1.0f - delta * _linearDamping, 0.0f, 1.0f);
667	        _cpBody->w *= cpfclamp(1.0f - delta * _angularDamping, 0.0f, 1.0f);
668	    }
669	}
