456	void PhysicsBody::setMass(float mass)
457	{
458	    if (mass <= 0)
459	    {
460	        return;
461	    }
462	    _mass = mass;
463	    _massDefault = false;
464	    _massSetByUser = true;
465	    
466	    // update density
467	    if (_mass == PHYSICS_INFINITY)
468	    {
469	        _density = PHYSICS_INFINITY;
470	    }
471	    else
472	    {
473	        if (_area > 0)
474	        {
475	            _density = _mass / _area;
476	        }else
477	        {
478	            _density = 0;
479	        }
480	    }
481	    
482	    // the static body's mass and moment is always infinity
483	    if (_dynamic)
484	    {
485	        internalBodySetMass(_cpBody, _mass);
486	    }
487	}
488	
489	void PhysicsBody::addMass(float mass)
490	{
491	    if (mass == PHYSICS_INFINITY)
492	    {
493	        _mass = PHYSICS_INFINITY;
494	        _massDefault = false;
495	        _density = PHYSICS_INFINITY;
496	    }
497	    else if (mass == -PHYSICS_INFINITY)
498	    {
499	        return;
500	    }
501	    else
502	    {
503	        if (_massDefault)
504	        {
505	            _mass = 0;
506	            _massDefault = false;
507	        }
508	        
509	        if (_mass + mass > 0)
510	        {
511	            _mass +=  mass;
512	        }else
513	        {
514	            _mass = MASS_DEFAULT;
515	            _massDefault = true;
516	        }
517	        
518	        if (_area > 0)
519	        {
520	            _density = _mass / _area;
521	        }
522	        else
523	        {
524	            _density = 0;
525	        }
526	    }
527	    
528	    // the static body's mass and moment is always infinity
529	    if (_dynamic)
530	    {
531	        internalBodySetMass(_cpBody, _mass);
532	    }
533	}
534	
535	void PhysicsBody::addMoment(float moment)
536	{
537	    if (moment == PHYSICS_INFINITY)
538	    {
539	        // if moment is PHYSICS_INFINITY, the moment of the body will become PHYSICS_INFINITY
540	        _moment = PHYSICS_INFINITY;
541	        _momentDefault = false;
542	    }
543	    else if (moment == -PHYSICS_INFINITY)
544	    {
545	        return;
546	    }
547	    else
548	    {
549	        // if moment of the body is PHYSICS_INFINITY is has no effect
550	        if (_moment != PHYSICS_INFINITY)
551	        {
552	            if (_momentDefault)
553	            {
554	                _moment = 0;
555	                _momentDefault = false;
556	            }
557	            
558	            if (_moment + moment > 0)
559	            {
560	                _moment += moment;
561	            }
562	            else
563	            {
564	                _moment = MOMENT_DEFAULT;
565	                _momentDefault = true;
566	            }
567	        }
568	    }
569	    
570	    // the static body's mass and moment is always infinity
571	    if (_rotationEnabled && _dynamic)
572	    {
573	        cpBodySetMoment(_cpBody, _moment);
574	    }
575	}
