677	void PhysicsBody::removeShape(PhysicsShape* shape, bool reduceMassAndMoment/* = true*/)
678	{
679	    if (_shapes.getIndex(shape) != -1)
680	    {
681	        // deduce the area, mass and moment
682	        // area must update before mass, because the density changes depend on it.
683	        if (reduceMassAndMoment)
684	        {
685	            _area -= shape->getArea();
686	            addMass(-shape->getMass());
687	            addMoment(-shape->getMoment());
688	        }
689	        
690	        //remove
691	        if (_world)
692	        {
693	            _world->removeShape(shape);
694	        }
695	        
696	        // set shape->_body = nullptr make the shape->setBody will not trigger the _body->removeShape function call.
697	        shape->_body = nullptr;
698	        shape->setBody(nullptr);
699	        _shapes.eraseObject(shape);
700	    }
701	}
