703	void PhysicsBody::removeAllShapes(bool reduceMassAndMoment/* = true*/)
704	{
705	    for (auto& child : _shapes)
706	    {
707	        PhysicsShape* shape = dynamic_cast<PhysicsShape*>(child);
708	        
709	        // deduce the area, mass and moment
710	        // area must update before mass, because the density changes depend on it.
711	        if (reduceMassAndMoment)
712	        {
713	            _area -= shape->getArea();
714	            addMass(-shape->getMass());
715	            addMoment(-shape->getMoment());
716	        }
717	        
718	        if (_world)
719	        {
720	            _world->removeShape(shape);
721	        }
722	        
723	        // set shape->_body = nullptr make the shape->setBody will not trigger the _body->removeShape function call.
724	        shape->_body = nullptr;
725	        shape->setBody(nullptr);
726	    }
727	    
728	    _shapes.clear();
729	}
