772	void PhysicsBody::update(float delta)
773	{
774	    // damping compute
775	    if (_isDamping && _dynamic && !isResting())
776	    {
777	        _cpBody->v.x *= cpfclamp(1.0f - delta * _linearDamping, 0.0f, 1.0f);
